-- =====================================================================================
-- SGI Di Égida · Propuestas de almacenamiento de MPI desde el registro de producción de cocina
-- Generado por scripts/migracion/proponer_produccion.mjs desde referencia/REG-COC-007-Plantilla-Produccion-v1.0.xlsx
-- (234 lotes). NO editar a mano. Solo propuestas: se aceptan en /catalogo/unidades.
-- Idempotente: al volver a cargarlo actualiza solo las pendientes.
-- =====================================================================================

on conflict (id) do update set cambios = excluded.cambios, actual = excluded.actual, seguridad = excluded.seguridad, razon = excluded.razon
  where public.propuestas_unidad.estado = 'PENDIENTE' and public.propuestas_unidad.cambios is distinct from excluded.cambios;

-- la propuesta de unidad que aún esté pendiente para estos productos queda reemplazada por esta
update public.propuestas_unidad set estado = 'REEMPLAZADA', mensaje = 'Reemplazada por la propuesta del registro de producción.'
